import { OPS, Util } from "../shared/util.js";
import { IDENTITY_MATRIX } from "../core/core_utils.js";
// eslint-disable-next-line import/no-cycle
import { StateManager, TextState } from "./evaluator.js";
import { Dict } from "./primitives.js";

class BoundingBoxesCalculator {
  constructor(ignoreCalculations, textState = null, graphicsState = null) {
    this.textStateManager = new StateManager(textState || new TextState());
    this.graphicsStateManager = new StateManager(
      graphicsState || new GraphicsState()
    );
    this.clipping = false;
    this.boundingBoxesStack = new NoMCIDBoundingBoxStack();
    this.boundingBoxes = {};
    this.refBoundingBoxes = {};
    this.ignoreCalculations = ignoreCalculations;
    this.operationArray = [];
    this.mcidArray = [];
    this.sameMcidDepth = 0;
    this.operationIndex = -1;
  }

  transformPoint(x, y, ctm) {
    const p = [x, y];
    Util.applyTransform(p, ctm);
    return p;
  }

  // Get Top points of rectangle:
  // rectangle corners ABCD (clockwise starting with left bottom corner)
  // rectangle base AB: A(x0, y0), B(x1, y1)
  // rectangle height h
  // return CD
  getTopPoints(x0, y0, x1, y1, h) {
    const l = Math.hypot(x1 - x0, y1 - y0); // base length
    if (l === 0) {
      return [x1 + h, y1 + h, x0 + h, y0 + h];
    }

    const e = [(x1 - x0) / l, (y1 - y0) / l]; // get unit vector for line connecting A and B

    const rotated_e = [-e[1], e[0]]; // rotate unit vector by 90 deg to the left
    const result_vector = [rotated_e[0] * h, rotated_e[1] * h]; // scale unit vactor

    return [
      x1 + result_vector[0],
      y1 + result_vector[1],
      x0 + result_vector[0],
      y0 + result_vector[1],
    ];
  }

  getTextBoundingBox(glyphs) {
    let tx = 0;
    let ty = 0;
    // Save previous x value to take it into account while calculating
    // width of marked content

    const ctm = this.graphicsStateManager.state.ctm;

    const descent =
      (this.textStateManager.state.font.descent || 0) *
      this.textStateManager.state.fontSize;
    const ascent =
      (this.textStateManager.state.font.ascent || 1) *
      this.textStateManager.state.fontSize;
    const rise =
      this.textStateManager.state.textRise *
      this.textStateManager.state.fontSize;

    let tx0, ty0, shift, height;
    if (!this.textStateManager.state.font.vertical) {
      // Left Bottom point of text bbox
      // Save before text matrix will be changed with going through glyphs
      [tx0, ty0] = this.transformPoint(
        0,
        descent + rise,
        this.textStateManager.state.textMatrix
      );
      // Calculate transformed height and shift to place
      // the whole glyph inside the bbox
      shift = [
        tx0 - this.textStateManager.state.textMatrix[4],
        ty0 - this.textStateManager.state.textMatrix[5],
      ];
      height = this.transformPoint(
        0,
        ascent - descent,
        this.textStateManager.state.textMatrix
      );
    } else {
      [tx0, ty0] = this.transformPoint(
        -this.textStateManager.state.fontSize / 2,
        rise,
        this.textStateManager.state.textMatrix
      );
      shift = [
        tx0 - this.textStateManager.state.textMatrix[4],
        ty0 - this.textStateManager.state.textMatrix[5],
      ];
      height = this.transformPoint(
        ascent - descent,
        0,
        this.textStateManager.state.textMatrix
      );
    }
    height[0] -= this.textStateManager.state.textMatrix[4];
    height[1] -= this.textStateManager.state.textMatrix[5];
    height = Math.hypot(height[0], height[1]);
    height *=
      this.textStateManager.state.textMatrix[0] *
        this.textStateManager.state.textMatrix[3] <
      0
        ? -1
        : 1;

    let glyphsSize = [];
    for (let i = 0; i < glyphs.length; i++) {
      const glyph = glyphs[i];
      if (typeof glyph === "number") {
        if (this.textStateManager.state.font.vertical) {
          ty =
            (-glyph / 1000) *
            this.textStateManager.state.fontSize *
            this.textStateManager.state.textHScale;
        } else {
          tx =
            (-glyph / 1000) *
            this.textStateManager.state.fontSize *
            this.textStateManager.state.textHScale;
        }
      } else {
        let glyphWidth = null;
        glyphWidth =
          this.textStateManager.state.font.vertical && glyph.vmetric
            ? glyph.vmetric[0]
            : glyph.width;
        if (!this.textStateManager.state.font.vertical) {
          const w0 =
            glyphWidth *
            (this.textStateManager.state.fontMatrix
              ? this.textStateManager.state.fontMatrix[0]
              : 1 / 1000);
          tx =
            (w0 * this.textStateManager.state.fontSize +
              this.textStateManager.state.charSpacing +
              (glyph.isSpace ? this.textStateManager.state.wordSpacing : 0)) *
            this.textStateManager.state.textHScale;
        } else {
          const w1 =
            glyphWidth *
            (this.textStateManager.state.fontMatrix
              ? this.textStateManager.state.fontMatrix[0]
              : 1 / 1000);
          ty =
            w1 * this.textStateManager.state.fontSize -
            this.textStateManager.state.charSpacing -
            (glyph.isSpace ? this.textStateManager.state.wordSpacing : 0);
        }
      }
      const [x, y] = [
        this.textStateManager.state.textMatrix[4] + shift[0],
        this.textStateManager.state.textMatrix[5] + shift[1],
      ];
      this.textStateManager.state.translateTextMatrix(tx, -ty);
      if (typeof glyph !== "number") {
        glyphsSize.push([
          x,
          y,
          this.textStateManager.state.textMatrix[4] + shift[0],
          this.textStateManager.state.textMatrix[5] + shift[1],
        ]);
      }
    }

    // Right Bottom point is in text matrix after going through glyphs
    const [tx1, ty1] = [
      this.textStateManager.state.textMatrix[4] + shift[0],
      this.textStateManager.state.textMatrix[5] + shift[1],
    ];
    // Top point can be calculated from base and height
    const [tx2, ty2, tx3, ty3] = this.getTopPoints(tx0, ty0, tx1, ty1, height);
    glyphsSize = glyphsSize.map(glyphSize => [
      ...glyphSize,
      ...this.getTopPoints(...glyphSize, height),
    ]);

    // Apply transform matrix to bbox
    const [x0, y0] = this.transformPoint(tx0, ty0, ctm);
    const [x1, y1] = this.transformPoint(tx1, ty1, ctm);
    const [x2, y2] = this.transformPoint(tx2, ty2, ctm);
    const [x3, y3] = this.transformPoint(tx3, ty3, ctm);
    glyphsSize = glyphsSize.map(glyphSize => [
      ...this.transformPoint(glyphSize[0], glyphSize[1], ctm),
      ...this.transformPoint(glyphSize[2], glyphSize[3], ctm),
      ...this.transformPoint(glyphSize[4], glyphSize[5], ctm),
      ...this.transformPoint(glyphSize[6], glyphSize[7], ctm),
    ]);
    let minX, maxX, minY, maxY;
    const glyphsPos = [];
    glyphsSize.forEach(glyphSize => {
      const xPoints = [...glyphSize].filter((point, index) => index % 2 === 0);
      const yPoints = [...glyphSize].filter((point, index) => index % 2 !== 0);
      minX = Math.min(...xPoints);
      maxX = Math.max(...xPoints);

      minY = Math.min(...yPoints);
      maxY = Math.max(...yPoints);
      glyphsPos.push([minX, minY, maxX - minX, maxY - minY]);
    });
    this.operationArray[this.operationIndex] = glyphsPos;

    minX = Math.min(x0, x1, x2, x3);
    maxX = Math.max(x0, x1, x2, x3);

    minY = Math.min(y0, y1, y2, y3);
    maxY = Math.max(y0, y1, y2, y3);

    this.boundingBoxesStack.save(minX, minY, maxX - minX, maxY - minY);
  }

  getClippingGraphicsBoundingBox() {
    const state = this.graphicsStateManager.state;

    if (state.clip === null) {
      return {
        x: state.x,
        y: state.y,
        w: state.w,
        h: state.h,
      };
    }

    if (
      (state.x < state.clip.x && state.x + state.w < state.clip.x) ||
      (state.x > state.clip.x + state.clip.w &&
        state.x + state.w > state.clip.x + state.clip.w) ||
      (state.y < state.clip.y && state.y + state.h < state.clip.y) ||
      (state.y > state.clip.y + state.clip.h &&
        state.y + state.h > state.clip.y + state.clip.h)
    ) {
      return null;
    }

    return {
      x: Math.max(state.x, state.clip.x),
      y: Math.max(state.y, state.clip.y),
      w:
        Math.min(state.x + state.w, state.clip.x + state.clip.w) -
        Math.max(state.x, state.clip.x),
      h:
        Math.min(state.y + state.h, state.clip.y + state.clip.h) -
        Math.max(state.y, state.clip.y),
    };
  }

  saveGraphicsBoundingBox() {
    const clippingBBox = this.getClippingGraphicsBoundingBox();
    if (clippingBBox === null) {
      return;
    }

    const x = clippingBBox.x;
    const y = clippingBBox.y;
    const w = clippingBBox.w;
    const h = clippingBBox.h;

    this.graphicsStateManager.state.x = null;
    this.graphicsStateManager.state.y = null;
    this.graphicsStateManager.state.w = null;
    this.graphicsStateManager.state.h = null;

    this.boundingBoxesStack.save(x, y, w, h);
  }

  getRectBoundingBox(x, y, w, h) {
    const state = this.graphicsStateManager.state;

    const [x1, y1] = this.transformPoint(x, y, state.ctm);
    const [x2, y2] = this.transformPoint(x + w, y, state.ctm);
    const [x3, y3] = this.transformPoint(x, y + h, state.ctm);
    const [x4, y4] = this.transformPoint(x + w, y + h, state.ctm);

    x = Math.min(x1, x2, x3, x4);
    y = Math.min(y1, y2, y3, y4);
    w = Math.max(x1, x2, x3, x4) - x;
    h = Math.max(y1, y2, y3, y4) - y;

    if (state.w === null) {
      state.w = Math.abs(w);
    } else {
      state.w =
        Math.max(state.x + state.w, x, x + w) - Math.min(state.x, x, x + w);
    }

    if (state.h === null) {
      state.h = Math.abs(h);
    } else {
      state.h =
        Math.max(state.y + state.h, y, y + h) - Math.min(state.y, y, y + h);
    }

    state.x =
      state.x === null ? Math.min(x, x + w) : Math.min(state.x, x, x + w);

    state.y =
      state.y === null ? Math.min(y, y + h) : Math.min(state.y, y, y + h);
  }

  getLineBoundingBox(x, y) {
    const state = this.graphicsStateManager.state;

    [x, y] = this.transformPoint(x, y, state.ctm);

    if (state.w === null) {
      state.w = Math.abs(x - state.move_x);
    } else {
      state.w =
        Math.max(x, state.move_x, state.x + state.w) -
        Math.min(x, state.move_x, state.x);
    }

    if (state.h === null) {
      state.h = Math.abs(y - state.move_y);
    } else {
      state.h =
        Math.max(y, state.move_y, state.y + state.h) -
        Math.min(y, state.move_y, state.y);
    }

    state.x =
      state.x === null
        ? Math.min(x, state.move_x)
        : Math.min(x, state.move_x, state.x);

    state.y =
      state.y === null
        ? Math.min(y, state.move_y)
        : Math.min(y, state.move_y, state.y);

    // Next line will start from the end of current line
    state.move_x = x;
    state.move_y = y;
  }

  getCurve(a, b, c, d) {
    return function curve(t) {
      return (
        (1 - t) ** 3 * a +
        3 * t * (1 - t) ** 2 * b +
        3 * t * t * (1 - t) * c +
        t * t * t * d
      );
    };
  }

  // Equate the derivative to zero in order to find
  // local extremum and solve the equation
  getCurveRoots(a, b, c, d) {
    let root_1;
    let root_2;

    const sqrt =
      (6 * a - 12 * b + 6 * c) ** 2 -
      4 * (3 * b - 3 * a) * (-3 * a + 9 * b - 9 * c + 3 * d);
    root_1 = null;
    root_2 = null;

    // Calculate roots if equation has roots and they are real
    // Equation has infinite(too big) roots if denominator is too small
    if (Math.abs(a + 3 * c - 3 * b - d) > 0.1 ** -10) {
      if (sqrt >= 0) {
        root_1 =
          (-6 * a + 12 * b - 6 * c + Math.sqrt(sqrt)) /
          (2 * (-3 * a + 9 * b - 9 * c + 3 * d));
        root_2 =
          (-6 * a + 12 * b - 6 * c - Math.sqrt(sqrt)) /
          (2 * (-3 * a + 9 * b - 9 * c + 3 * d));
      }
    } else if (sqrt > 0.1 ** -10) {
      root_1 = (a - b) / (2 * a - 4 * b + 2 * c);
    }

    // We are only interested in roots that lay in range from 0 to 1
    // Ignore other ones
    if (root_1 !== null && (root_1 < 0 || root_1 > 1)) {
      root_1 = null;
    }
    if (root_2 !== null && (root_2 < 0 || root_2 > 1)) {
      root_2 = null;
    }

    return [root_1, root_2];
  }

  getCurveBoundingBox(op, x0, y0, x1, y1, x2, y2, x3, y3) {
    const state = this.graphicsStateManager.state;

    if (op !== OPS.curveTo2) {
      [x1, y1] = this.transformPoint(x1, y1, state.ctm);
    }
    [x2, y2] = this.transformPoint(x2, y2, state.ctm);
    [x3, y3] = this.transformPoint(x3, y3, state.ctm);

    const curveX = this.getCurve(x0, x1, x2, x3);
    const curveY = this.getCurve(y0, y1, y2, y3);

    let [root_1, root_2] = this.getCurveRoots(x0, x1, x2, x3);

    const minX = Math.min(
      x0,
      x3,
      root_1 !== null ? curveX(root_1) : Number.MAX_VALUE,
      root_2 !== null ? curveX(root_2) : Number.MAX_VALUE
    );
    const maxX = Math.max(
      x0,
      x3,
      root_1 !== null ? curveX(root_1) : Number.MIN_VALUE,
      root_2 !== null ? curveX(root_2) : Number.MIN_VALUE
    );

    [root_1, root_2] = this.getCurveRoots(y0, y1, y2, y3);

    const minY = Math.min(
      y0,
      y3,
      root_1 !== null ? curveY(root_1) : Number.MAX_VALUE,
      root_2 !== null ? curveY(root_2) : Number.MAX_VALUE
    );
    const maxY = Math.max(
      y0,
      y3,
      root_1 !== null ? curveY(root_1) : Number.MIN_VALUE,
      root_2 !== null ? curveY(root_2) : Number.MIN_VALUE
    );

    const x = minX;
    const y = minY;
    const h = maxY - minY;
    const w = maxX - minX;

    if (state.w === null) {
      state.w = Math.abs(w);
    } else {
      state.w =
        Math.max(state.x + state.w, x, x + w) - Math.min(state.x, x, x + w);
    }

    if (state.h === null) {
      state.h = Math.abs(h);
    } else {
      state.h =
        Math.max(state.y + state.h, y, y + h) - Math.min(state.y, y, y + h);
    }

    state.x =
      state.x === null ? Math.min(x, x + w) : Math.min(state.x, x, x + w);

    state.y =
      state.y === null ? Math.min(y, y + h) : Math.min(state.y, y, y + h);

    state.move_x = x;
    state.move_y = y;
  }

  getClip() {
    if (this.clipping) {
      const state = this.graphicsStateManager.state;
      if (state.clip === null) {
        state.clip = {
          x: state.x,
          y: state.y,
          w: state.w,
          h: state.h,
        };
      } else {
        // Intersection with previous clip
        state.clip = {
          x: Math.max(state.x, state.clip.x),
          y: Math.max(state.y, state.clip.y),
          w:
            Math.min(state.x + state.w, state.clip.x + state.clip.w) -
            Math.max(state.x, state.clip.x),
          h:
            Math.min(state.y + state.h, state.clip.y + state.clip.h) -
            Math.max(state.y, state.clip.y),
        };
      }
      this.clipping = false;
    }
  }

  getNoMCIDBoundingBoxes() {
    return this.boundingBoxesStack.get();
  }

  getImageBoundingBox() {
    const state = this.graphicsStateManager.state;
    const [x0, y0] = this.transformPoint(0, 0, state.ctm);
    const [x1, y1] = this.transformPoint(0, 1, state.ctm);
    const [x2, y2] = this.transformPoint(1, 1, state.ctm);
    const [x3, y3] = this.transformPoint(1, 0, state.ctm);

    state.x = Math.min(x0, x1, x2, x3);
    state.y = Math.min(y0, y1, y2, y3);
    state.w = Math.max(x0, x1, x2, x3) - state.x;
    state.h = Math.max(y0, y1, y2, y3) - state.y;

    this.operationArray[this.operationIndex] = [[state.x, state.y, state.w, state.h]];
  }

  parseOperator(fn, args) {
    if (this.ignoreCalculations) {
      return;
    }

    if (
      fn !== OPS.markPoint &&
      fn !== OPS.markPointProps &&
      fn !== OPS.beginMarkedContent &&
      fn !== OPS.beginMarkedContentProps &&
      fn !== OPS.endMarkedContent
    ) {
      this.boundingBoxesStack.inc();
    }

    switch (fn | 0) {
      case OPS.restore:
        this.graphicsStateManager.restore();
        this.textStateManager.restore();
        break;
      case OPS.save:
        this.graphicsStateManager.save();
        this.textStateManager.save();
        break;
      case OPS.fill:
      case OPS.eoFill:
      case OPS.eoFillStroke:
      case OPS.fillStroke:
      case OPS.stroke:
      case OPS.closeEOFillStroke:
      case OPS.closeFillStroke:
      case OPS.closeStroke:
        this.getClip();
        this.saveGraphicsBoundingBox();
        break;
      case OPS.endPath:
        this.getClip();
        this.graphicsStateManager.state.clean();
        break;
      case OPS.transform:
        this.graphicsStateManager.state.ctm = Util.transform(
          this.graphicsStateManager.state.ctm,
          args
        );
        break;
      case OPS.clip:
      case OPS.eoClip:
        this.clipping = true;
        break;
      case OPS.setFont:
        this.textStateManager.state.fontSize = args[0];
        this.textStateManager.state.fontMatrix = args[1].font.fontMatrix;
        this.textStateManager.state.font = args[1].font;
        break;
      case OPS.setTextMatrix:
        this.textStateManager.state.setTextMatrix(
          args[0],
          args[1],
          args[2],
          args[3],
          args[4],
          args[5]
        );
        this.textStateManager.state.setTextLineMatrix(
          args[0],
          args[1],
          args[2],
          args[3],
          args[4],
          args[5]
        );
        break;
      case OPS.nextLine:
        this.textStateManager.state.carriageReturn();
        break;
      case OPS.setCharSpacing:
        this.textStateManager.state.charSpacing = args[0];
        break;
      case OPS.setWordSpacing:
        this.textStateManager.state.wordSpacing = args[0];
        break;
      case OPS.setHScale:
        this.textStateManager.state.textHScale = args[0] / 100;
        break;
      case OPS.setLeading:
        this.textStateManager.state.leading = args[0];
        break;
      case OPS.setTextRise:
        this.textStateManager.state.textRise = args[0];
        break;
      case OPS.setLeadingMoveText:
        this.textStateManager.state.leading = -args[1];
        this.textStateManager.state.translateTextLineMatrix(...args);
        this.textStateManager.state.textMatrix =
          this.textStateManager.state.textLineMatrix.slice();
        break;
      case OPS.moveText:
        this.textStateManager.state.translateTextLineMatrix(args[0], args[1]);
        this.textStateManager.state.textMatrix =
          this.textStateManager.state.textLineMatrix.slice();
        break;
      case OPS.beginText:
        this.textStateManager.state.textMatrix = IDENTITY_MATRIX.slice();
        this.textStateManager.state.textLineMatrix = IDENTITY_MATRIX.slice();
        break;
      case OPS.moveTo:
        const ctm = this.graphicsStateManager.state.ctm.slice();
        [
          this.graphicsStateManager.state.move_x,
          this.graphicsStateManager.state.move_y,
        ] = this.transformPoint(args[0], args[1], ctm);
        break;
      case OPS.lineTo:
        this.getLineBoundingBox(args[0], args[1]);
        break;
      case OPS.curveTo:
        this.getCurveBoundingBox(
          OPS.curveTo,
          this.graphicsStateManager.state.move_x,
          this.graphicsStateManager.state.move_y,
          args[0],
          args[1],
          args[2],
          args[3],
          args[4],
          args[5]
        );
        break;
      case OPS.curveTo2:
        this.getCurveBoundingBox(
          OPS.curveTo2,
          this.graphicsStateManager.state.move_x,
          this.graphicsStateManager.state.move_y,
          this.graphicsStateManager.state.move_x,
          this.graphicsStateManager.state.move_y,
          args[0],
          args[1],
          args[2],
          args[3]
        );
        break;
      case OPS.curveTo3:
        this.getCurveBoundingBox(
          OPS.curveTo3,
          this.graphicsStateManager.state.move_x,
          this.graphicsStateManager.state.move_y,
          args[0],
          args[1],
          args[2],
          args[3],
          args[2],
          args[3]
        );
        break;
      case OPS.rectangle:
        this.getRectBoundingBox(args[0], args[1], args[2], args[3]);
        break;
      case OPS.markPoint:
      case OPS.markPointProps:
      case OPS.beginMarkedContent:
        // Marked content forms the scope
        this.boundingBoxesStack.begin();
        break;
      case OPS.beginMarkedContentProps:
        if (args[1] instanceof Dict && args[1].has("MCID")) {
          const mcid = args[1].get("MCID");

          // Prevent parsing of Marked content with same MCIDs
          if (this.mcidArray.includes(mcid)) {
            this.sameMcidDepth++;
            break;
          } else {
            this.mcidArray.push(mcid);
          }
          this.boundingBoxesStack.begin(mcid);

          // Clear graphics bounding box to split graphics
          // in different marked content
          this.graphicsStateManager.state.x = null;
          this.graphicsStateManager.state.y = null;
          this.graphicsStateManager.state.w = null;
          this.graphicsStateManager.state.h = null;
        } else {
          // Marked content with no MCID still forms the scope
          this.boundingBoxesStack.begin();
        }
        break;
      case OPS.endMarkedContent:
        if (this.sameMcidDepth !== 0) {
          this.sameMcidDepth--;
          break;
        }

        const boundingBox = this.boundingBoxesStack.end();
        if (boundingBox !== null) {
          this.boundingBoxes[boundingBox.mcid] = {
            x: boundingBox.x,
            y: boundingBox.y,
            width: boundingBox.w,
            height: boundingBox.h,
          };
        }
        break;
      case OPS.paintXObject:
        const [type, bboxes] = args;
        if (type === "Image") {
          this.getImageBoundingBox();
          this.saveGraphicsBoundingBox();
        } else if (type === "Form" && typeof bboxes === "object") {
          const opArr = Object.values(bboxes).map((b) => {
            let { contentItems, contentItem } = b;
            while (contentItems?.length) {
              [{ contentItems, contentItem }] = contentItems;
            }
            if (contentItem?.x == null) return [];
            const { x, y, w, h } = contentItem;
            return [x, y, w, h];
          });
          this.operationArray[this.operationIndex] = opArr;
        }
        break;
      case OPS.showText:
        this.getTextBoundingBox(args[0]);
        break;
      default:
        break;
    }
  }

  setFont(translated) {
    this.textStateManager.state.fontMatrix = translated.font.fontMatrix;
    this.textStateManager.state.font = translated.font;
  }

  incrementOperation() {
    if (this.ignoreCalculations) {
      return;
    }
    this.operationIndex++;
  }

  addRefBoundingBoxes(objId, boundingBoxes) {
    this.refBoundingBoxes[objId] = boundingBoxes;
  }

  get textState() {
    return this.textStateManager.state;
  }

  get graphicsState() {
    return this.graphicsStateManager.state;
  }

  saveState() {
    this.textStateManager.save();
    this.graphicsStateManager.save();
  }

  restoreState() {
    this.textStateManager.restore();
    this.graphicsStateManager.restore();
  }
}

class GraphicsState {
  constructor() {
    this.x = null;
    this.y = null;
    this.w = null;
    this.h = null;
    this.move_x = null;
    this.move_y = null;
    this.ctm = IDENTITY_MATRIX.slice();
    this.clip = null;
  }

  clone() {
    const clone = Object.create(this);
    clone.ctm = this.ctm.slice();
    return clone;
  }

  clean() {
    this.x = null;
    this.y = null;
    this.w = null;
    this.h = null;
    this.move_x = 0;
    this.move_y = 0;
    // this.ctm = IDENTITY_MATRIX.slice();
    // clip state stays the same
  }
}

class BoundingBoxStack {
  constructor() {
    this.stack = [];
  }

  begin(mcid) {
    this.stack.push({
      x: null,
      y: null,
      w: null,
      h: null,
      mcid: Number.isInteger(mcid) ? mcid : null,
    });
  }

  save(x, y, w, h) {
    const current = this.stack.at(-1);

    if (!current) {
      return;
    }

    current.w =
      current.w !== null
        ? Math.max(current.x + current.w, x + w) - Math.min(current.x, x)
        : w;

    current.x = current.x !== null ? Math.min(current.x, x) : x;

    current.h =
      current.h !== null
        ? Math.max(current.y + current.h, y + h) - Math.min(current.y, y)
        : h;

    current.y = current.y !== null ? Math.min(current.y, y) : y;
  }

  end() {
    const last = this.stack.pop();

    if (!last) {
      return null;
    }

    if (last.mcid !== null) {
      return last;
    }

    this.save(last.x, last.y, last.w, last.h);
    return null;
  }
}

class NoMCIDBoundingBoxStack {
  constructor() {
    this.boundingBoxesStack = new BoundingBoxStack();
    this.contentCounter = null;
    this.content = {};
    this.pointer = {};
  }

  begin(mcid) {
    if (!this.contentCounter || this.contentCounter.inMarkedContent !== false) {
      this.inc(true);
    } else {
      const newContentItem = { parent: this.pointer, contentItems: [] };
      this.pointer.contentItems.push(newContentItem);
      this.pointer = newContentItem;
    }
    this.boundingBoxesStack.begin(mcid);
  }

  save(x, y, w, h) {
    if (this.pointer.contentItems) {
      this.pointer.contentItems.push({
        contentItem: { x, y, w, h },
      });
      this.pointer.final = true;
    } else {
      console.log(
        "NoMCIDBoundingBoxStackError:",
        "The pointer was in an invalid state, saved data will be lost"
      );
    }
    this.boundingBoxesStack.save(x, y, w, h);
  }

  end() {
    const tempPointer = this.pointer;
    this.pointer = tempPointer.parent || this.content;
    delete tempPointer.parent;

    if (this.pointer === this.content) {
      this.contentCounter.inMarkedContent = null;
      this.pointer = {};
    }

    return this.boundingBoxesStack.end();
  }

  inc(isMC = false) {
    if (!this.contentCounter) {
      this.contentCounter = { index: 0, inMarkedContent: !isMC };
      this.content[this.contentCounter.index] = {
        parent: this.content,
        contentItems: [],
      };
      this.pointer = this.content[this.contentCounter.index];
    } else if (
      (this.contentCounter.inMarkedContent !== false && isMC) ||
      (!!this.contentCounter.inMarkedContent === isMC &&
        !Object.keys(this.pointer).length)
    ) {
      delete this.content[this.contentCounter.index].parent;
      this.contentCounter = {
        index: this.contentCounter.index + 1,
        inMarkedContent: !isMC,
      };
      this.content[this.contentCounter.index] = {
        parent: this.content,
        contentItems: [],
      };
      this.pointer = this.content[this.contentCounter.index];
    }
  }

  get() {
    try {
      if (Object.keys(this.content).length && this.contentCounter) {
        if (this.content[this.contentCounter.index].parent) {
          delete this.content[this.contentCounter.index].parent;
        }
        const result = JSON.parse(JSON.stringify(this.content));
        this.content[this.contentCounter.index].parent = this.content;
        return result;
      }
      return {};
    } catch (err) {
      console.log("NoMCIDBoundingBoxStackError:", err.message || err);
      return {};
    }
  }
}

export { BoundingBoxesCalculator };
